    }

    // Change-based recommendations
    if (changes.consoleImplementations.length > 0) {
      recommendations.push('Consider implementing real-time data integration for console interfaces');
      recommendations.push('Add AI-powered insights to enhance console capabilities');
    }

    if (changes.componentsAdded.length > 0) {
      recommendations.push('Implement comprehensive testing for new components');
      recommendations.push('Add accessibility compliance checks for new interfaces');
    }

    // Layer-specific recommendations
    if (layerTestResults && layerTestResults.layers) {
      Object.entries(layerTestResults.layers).forEach(([layerName, layerData]) => {
        if (layerData.score < 80) {
          const priority = layerData.health === 'critical' ? 'HIGH PRIORITY' : 'MEDIUM PRIORITY';
          recommendations.push(`${priority}: Improve ${layerName} layer (${layerData.score}/100)`);

          // Add top 2 recommendations for each layer
          layerData.recommendations.slice(0, 2).forEach(rec => {
            recommendations.push(`  - ${rec}`);
          });
        }
      });
    }

    // Overall layer health recommendations
    if (layerTestResults && layerTestResults.overallHealth) {
      const health = layerTestResults.overallHealth;
      if (health.overall === 'critical') {
        recommendations.push('CRITICAL: Address layer health issues immediately');
      } else if (health.overall === 'warning') {
        recommendations.push('WARNING: Monitor layer health and address issues soon');
      } else {
        recommendations.push('All layers healthy - focus on feature development and optimization');
      }
    }

    // General recommendations
    recommendations.push('Continue with cross-holon dependency mapping');
    recommendations.push('Implement automated issue categorization');
    recommendations.push('Enhance system monitoring and alerting');

    return recommendations;
  }

